{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_def",
      "facet": "mechanism",
      "statement": "Binary search searches a sorted array by repeatedly dividing the search interval in half, narrowing to the lower or upper half based on the search key until the value is found or the interval is empty.",
      "start_line": 4,
      "end_line": 9
    },
    {
      "key": "obs_precondition",
      "facet": "precondition",
      "statement": "The array being searched must be sorted.",
      "start_line": 5,
      "end_line": 6
    },
    {
      "key": "obs_term_dichotomic",
      "facet": "term",
      "statement": "Binary search is a kind of dichotomic search.",
      "start_line": 10,
      "end_line": 12
    },
    {
      "key": "obs_relation_sort",
      "facet": "relation",
      "statement": "Binary search is used in binary insertion sort.",
      "start_line": 16,
      "end_line": 18
    },
    {
      "key": "obs_relation_merge",
      "facet": "relation",
      "statement": "Binary search is used in ideal merge.",
      "start_line": 19,
      "end_line": 20
    },
    {
      "key": "obs_relation_suffix",
      "facet": "relation",
      "statement": "Binary search is used in suffix array.",
      "start_line": 21,
      "end_line": 22
    },
    {
      "key": "obs_relation_inversion",
      "facet": "relation",
      "statement": "Binary search is used in inversion list.",
      "start_line": 23,
      "end_line": 24
    },
    {
      "key": "obs_mechanism_category",
      "facet": "mechanism",
      "statement": "Binary search is a part of or used in divide and conquer.",
      "start_line": 26,
      "end_line": 28
    },
    {
      "key": "obs_runtime",
      "facet": "property",
      "statement": "The run time of binary search is O(ln n).",
      "start_line": 39,
      "end_line": 41
    },
    {
      "key": "obs_overflow_risk",
      "facet": "precondition",
      "statement": "Calculating the middle index as (high + low)/2 overflows if high and low are close to the largest expressible integer.",
      "start_line": 43,
      "end_line": 45
    },
    {
      "key": "obs_safe_mid",
      "facet": "mechanism",
      "statement": "Calculating the middle index as low + (high - low)/2 gives the same result as (high + low)/2 and never overflows if high and low are non-negative.",
      "start_line": 45,
      "end_line": 46
    },
    {
      "key": "obs_linked_list_traversal",
      "facet": "property",
      "statement": "Binary search on an ordered linked list makes O(n) traversals.",
      "start_line": 48,
      "end_line": 51
    },
    {
      "key": "obs_linked_list_comparisons",
      "facet": "property",
      "statement": "Binary search on an ordered linked list performs O(log n) comparisons.",
      "start_line": 48,
      "end_line": 52
    },
    {
      "key": "obs_ref_wright",
      "facet": "reference",
      "statement": "Colin D. Wright is credited for the safe middle calculation note on 1 June 2005.",
      "start_line": 47,
      "end_line": 47
    },
    {
      "key": "obs_impl_python",
      "facet": "reference",
      "statement": "Recursive and iterative implementations of binary search are available in Python.",
      "start_line": 55,
      "end_line": 56
    },
    {
      "key": "obs_impl_c",
      "facet": "reference",
      "statement": "A C implementation of binary search using 0-based indexing is available.",
      "start_line": 58,
      "end_line": 60
    },
    {
      "key": "obs_impl_java",
      "facet": "reference",
      "statement": "Java explanations of binary search are available.",
      "start_line": 62,
      "end_line": 62
    },
    {
      "key": "obs_impl_cpp",
      "facet": "reference",
      "statement": "Java and C++ explanations of binary search are available in 'Algorithms and Data Structures'.",
      "start_line": 63,
      "end_line": 64
    },
    {
      "key": "obs_impl_ada",
      "facet": "reference",
      "statement": "Worst-case behavior annotated for real time is available in WOOP/ADA, including bibliography.",
      "start_line": 65,
      "end_line": 67
    },
    {
      "key": "obs_ref_dads",
      "facet": "reference",
      "statement": "The entry is from the Dictionary of Algorithms and Data Structures, edited by Paul E. Black.",
      "start_line": 70,
      "end_line": 83
    }
  ],
  "claims": [
    {
      "key": "claim_safe_mid",
      "status": "DERIVED_INTERPRETATION",
      "statement": "Using `low + (high - low)/2` is a safer alternative to `(high + low)/2` for calculating the middle index in binary search when indices are non-negative, as it prevents integer overflow.",
      "supported_by": [
        "obs_overflow_risk",
        "obs_safe_mid"
      ]
    },
    {
      "key": "claim_linked_list_tradeoff",
      "status": "DERIVED_INTERPRETATION",
      "statement": "Binary search on an ordered linked list offers fewer comparisons (O(log n)) than linear search but requires more traversals (O(n)) than typical array-based binary search, making it less efficient for traversal-heavy contexts despite comparison savings.",
      "supported_by": [
        "obs_linked_list_traversal",
        "obs_linked_list_comparisons"
      ]
    }
  ],
  "questions": []
}
